// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

function mousePressed() {
  redraw();
}

function setup() {
  createCanvas(w, h);
  pixelDensity(2);
  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  background(220);

  push();
  translate(w/2, h/2);

  var nn = 126;

  for(let j = 0; j < nn; j++) {

    var type = 0;
    if(random() < 0.2) {
      type = 1;
    }

    var cc = getColor();

    var di = 1;
    if(random() < 0.1) {
     di = 3; 
    }
    var l1 = random(di, 4*di);
    var l2 = random(di, 12*di);

    var sx = random(-w/2, w/2);
    var sy = random(-h/2, h/2);

    var pp = 10;
    var bb = 0.5;
    var v = 0.1;

    beginShape();

    for(let i = 0; i < pp; i++) {
      if(type < 0.5) {
        curveTightness(randomGaussian(1.5,0.2));      
      } else {
        curveTightness(1);
      }

      noFill();
      if(type < 0.5) {
        strokeWeight(random(2, 4));    
      } else {
        strokeWeight(2);  
      }
      stroke(cc);

      v += 0.05;
      var step, dir = 0.5;

      if(random() < bb) {
        step = random(0, w*v);
        if(random() < 0.5) {
          sx += step;
        } else {
          sx -= step;          
        }
        bb -= 0.1;
      } else {
        step = random(0, h*v);
        if(random() < 0.5) {
          sy += step;
        } else {
          sy -= step;          
        }
        bb += 0.1;
      }
      curveVertex(sx, sy);
    }
    endShape();

    fill(cc);
    noStroke();

    var kx = sx, ky = sy;
    var theta = random(0, 180), rad = 0;
    var cnt = 48;
    beginShape();
    for(let t = 0; t < cnt; t++) {
      theta += 360/(cnt* 1.2);
      rad = radians(theta);
      kx += random(0,l1)*cos(rad);
      ky += random(0,l2)*sin(rad);
      curveVertex(kx, ky);
    }
    curveVertex(sx, sy);
    endShape();
  }

  pop();

  drawGrids();
  drawFrame();
}

// ------------------------------ //
// ------------------------------ //
// ------------------------------ //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  }
}

function drawFrame() {
  rectMode(CENTER);

  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor() {
  var l = pal.length;
  var cc = random();
  // shuffle(pal, true);

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

